#include <algorithm>
#include <functional>
#include <set>
#include <string>
#include <vector>

// Used-array version.
std::vector<std::string> permutations(std::string s, bool dedupe = false) {
    if (dedupe) std::sort(s.begin(), s.end());
    std::vector<bool> used(s.size(), false);
    std::vector<std::string> out;
    std::string current;

    std::function<void()> backtrack = [&]() {
        if (current.size() == s.size()) {
            out.push_back(current);
            return;
        }
        for (size_t i = 0; i < s.size(); i++) {
            if (used[i]) continue;
            // Only the leftmost unused copy of a repeated character may go first.
            if (dedupe && i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;

            used[i] = true;
            current.push_back(s[i]);   // choose
            backtrack();               // explore
            current.pop_back();        // un-choose
            used[i] = false;
        }
    };

    backtrack();
    return out;
}

// Swap version.
std::vector<std::string> permutationsBySwap(std::string s) {
    std::vector<std::string> out;

    std::function<void(size_t)> backtrack = [&](size_t k) {
        if (k == s.size()) {
            out.push_back(s);
            return;
        }
        std::set<char> seen;
        for (size_t i = k; i < s.size(); i++) {
            if (seen.count(s[i])) continue;   // duplicate test, per level
            seen.insert(s[i]);

            std::swap(s[k], s[i]);   // choose
            backtrack(k + 1);        // explore
            std::swap(s[k], s[i]);   // un-choose
        }
    };

    backtrack(0);
    return out;
}
